#include <iostream>
using namespace std;

int main() {
    for(int i = 1; i <= 5; i++) {
        cout << i << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for(int i = 2; i <= 10; i+=2) {
        cout << i << " ";
    }
}

#include <iostream>
using namespace std;

int main() {
    int numbers[] = {1, 2, 3, 4, 5};
    for(int num : numbers) {
        cout << num << " ";
    }
}

#include <iostream>
using namespace std;

int main() {
    for(int i=0, j=10; i<5 && j>0; i++, j--) {
        cout << "i=" << i << ", j=" << j << endl;
    }
}

for (;;) {
    // Infinite loop
}

#include <iostream>
using namespace std;

int main() {
    for(int i = 1; i <= 3; i++) {
        for(int j = 1; j <= 3; j++) {
            cout << i * j << " ";
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for(int i = 0; i < 10; i += 2) {
        cout << i << " ";
    }
}

